<template>
  <div class="bjtj">
    <div class="serch">
      <el-form class="demo-ruleForm">
        <!-- <el-form-item label="矿名称" label-width="60px">
          <el-select v-model="mkname" placeholder="请选择矿名称" size="small" @change="handleSelect1()" clearable filterable>
            <span slot="prefix" class="select-icon">
              <img class="selectImg" src="../img/home/alarmlist/mk.png" alt="">
            </span>
            <el-option v-for="item in options1" :key="item.id" :label="item.mine_name" :value="item.id">
            </el-option>
          </el-select>
        </el-form-item> -->
        <el-form-item label="报警设备" label-width="100px">
          <img src="../img/home/alarmlist/video.png" alt="" class="cascaderImg">
          <el-cascader style="width:100%;" v-model="jkdname" :options="options2" :props="props" clearable size="small" @change="axioss()"></el-cascader>
        </el-form-item>
        <el-form-item label="报警类别" label-width="110px">
          <el-select v-model="template_type_id" placeholder="请选择报警类别" size="small" clearable filterable @change="axioss()">
            <span slot="prefix" class="select-icon">
              <img class="selectImg" src="../img/home/alarmlist/algorithm.png" alt="">
            </span>
            <el-option v-for="item in modelTypeOptions" :key="item.id+item.model_type_name" :label="item.model_type_name" :value="item.id"> </el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="报警等级" label-width="80px">
          <el-select v-model="bjtype" placeholder="请选择报警等级" size="small" clearable filterable @change="axioss()">
            <span slot="prefix" class="select-icon">
              <img class="selectImg" src="../img/home/alarmlist/alarm.png" alt="">
            </span>
            <el-option v-for="item in options3" :key="item.id" :label="item.value" :value="item.id"> </el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="报警时间" label-width="80px" prop="StartTime">
          <el-date-picker value-format="yyyy-MM-dd HH:mm:ss" type="datetime" v-model="StartTime" placeholder="选择时间" size="small" clearable :picker-options="pickerOptions" @change="axioss()">
          </el-date-picker>
        </el-form-item>
        <el-form-item label="至" label-width="30px" prop="EndTime">
          <el-date-picker value-format="yyyy-MM-dd HH:mm:ss" type="datetime" v-model="EndTime" placeholder="选择时间" size="small" clearable :picker-options="pickerOptions" @change="axioss()">
          </el-date-picker>
        </el-form-item>
        <el-form-item>
          <el-button type="primary" icon="el-icon-search" size="small" @click="axioss()">查询</el-button>
        </el-form-item>
        <!-- <el-form-item>
          <el-button type="success" size="small" @click="xz()">下载</el-button>
        </el-form-item> -->
      </el-form>
    </div>
    <div class="echarts">
      <div id="myChart1" style="width: 100%;height: 100%;" v-if="echartsTable.length != 0"></div>
      <!-- 如果没有数据，显示空状态 -->
      <el-empty v-if="echartsTable.length == 0" image="/static/img/home/placeholder_kong.png" :image-size="307" description="暂时没有数据~"></el-empty>
    </div>
  </div>
</template>

<script>
export default {
  name: "bjtj",
  data() {
    return {
      StartTime: "",
      EndTime: "",
      mkname: "",
      jkdname: "",
      template_type_id: "",
      bjtype: "",
      options1: [],
      options2: [],
      options3: [],
      modelTypeOptions: [],
      props: {
        checkStrictly: false,
        emitPath: false,
        value: 'id',
        label: 'equipment_name'
      },
      echartsTable: [],
      pickerOptions: {
        disabledDate(time) {
          // 获取当前日期的零时零分零秒
          const today = new Date();
          today.setHours(0, 0, 0, 0);
          // 禁用今天之后的所有日期和时间
          return time.getTime() > today.getTime();
        },
        disabledTime(time) {
          // 当StartTime为空时，不作任何限制
          if (!this.StartTime) return {};
          // 将StartTime字符串转换为Date对象
          const startTime = new Date(this.StartTime);
          // 禁止选择早于StartTime的时间
          return {
            disableTime: (time) => {
              return time.getTime() < startTime.getTime();
            }
          };
        },
      },
    }
  },
  methods: {
    formatDate(date) {
      const y = date.getFullYear();
      const m = String(date.getMonth() + 1).padStart(2, '0');
      const d = String(date.getDate()).padStart(2, '0');
      const h = String(date.getHours()).padStart(2, '0');
      const min = String(date.getMinutes()).padStart(2, '0');
      const s = String(date.getSeconds()).padStart(2, '0');
      return `${y}-${m}-${d} ${h}:${min}:${s}`;
    },
    handleSelect1() {
      // let param = new URLSearchParams();
      // param.append("mine_id", this.mkname);
      this.jkdname = ""
      this.$http.get(this.$url.url_5000 + "/model_view/type_select", {
        params: {
          mine_id: this.mkname
        }
      }, {
        withCredentials: true,
      })
        .then((response) => {
          console.log(response)
          if (response.data.code === 200) {
            this.options1 = response.data.mine_list
            this.options2 = response.data.equipment_list

            this.modelTypeOptions = response.data.model_type_template
            this.options3 = response.data.type_list
          }
        })
        .catch(function (response) {
          console.log(response);
        })
    },
    // axioss() {
    //   this.$http.get(this.$url.url_5000 + "/model_view/algorithm_ratio", {
    //     params: {
    //       mine_id: this.mkname,
    //       equipment_id: this.jkdname,
    //       start_time: this.StartTime,
    //       end_time: this.EndTime,
    //     }
    //   }, {
    //     withCredentials: true,
    //   })
    //     .then((response) => {
    //       console.log(response)
    //       if (response.data.code === 200) {
    //         this.echartsTable = response.data.data_list
    //         if (this.echartsTable.length != 0) {
    //           setTimeout(()=>{this.handleEchart()},1000)
    //         }
    //       }
    //     })
    //     .catch(function (response) {
    //       console.log(response);
    //     })
    // },
    axioss() {
      // 显示 loading 动画
      const loadingInstance = this.$loading({
        target: this.$el, // 选择要展示加载动画的目标 DOM
        text: '加载中...',  // 自定义 loading 文本
        spinner: 'el-icon-loading', // 设置 spinner 图标
      });

      // 发起请求
      this.$http.get(this.$url.url_5000 + "/model_view/algorithm_ratio", {
        params: {
          mine_id: this.mkname,
          equipment_id: this.jkdname,
          start_time: this.StartTime,
          end_time: this.EndTime,
          template_type_id: this.template_type_id,
          type: this.bjtype,
        }
      }, {
        withCredentials: true,
      })
        .then((response) => {
          // 请求成功后关闭 loading
          
          console.log(response);
          if (response.data.code === 200) {
            this.echartsTable = response.data.data_list;
            if (this.echartsTable.length !== 0) {
              setTimeout(() => { this.handleEchart()}, 1000);
            }
            // this.handleEchart()
          }
          setTimeout(() => {loadingInstance.close(); }, 1000);
        })
        .catch((error) => {
          // 请求失败后关闭 loading
          loadingInstance.close();
          console.log(error);
        });
    },
    handleEchart() {
      let myChart = this.$echarts.init(document.getElementById('myChart1'));

      let option = {
        title: {
          left: 'center',
          text: '报警统计' // 根据数据是否为空修改标题
        },
        tooltip: {
          trigger: 'item'
        },
        legend: {
          orient: 'vertical',
          left: '20',
          top: '20'
        },
        series: [
          {
            name: '报警统计',
            type: 'pie',
            radius: '70%',
            data: this.echartsTable, // 如果数据为空，显示“暂无数据”
            emphasis: {
              itemStyle: {
                shadowBlur: 10,
                shadowOffsetX: 0,
                shadowColor: 'rgba(0, 0, 0, 0.5)'
              }
            }
          }
        ],
      };

      myChart.setOption(option, true);
      myChart.resize();
    }
  },
  mounted() {
    const now = new Date();
    const currentTime = this.formatDate(now);

    // 当天零点时间
    const midnight = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const midnightTime = this.formatDate(midnight);

    this.StartTime = midnightTime;
    this.EndTime = currentTime;
    this.handleSelect1()
    this.axioss()
  }
}
</script>

<style lang="scss" scoped>
::v-deep.demo-ruleForm {
  .selectImg {
    width: 14px;
    height: 14px;
    margin-top: 13px;
    margin-left: 7px;
  }
  .cascaderImg {
    width: 14px;
    height: 14px;
    position: absolute;
    top: 13px;
    left: 13px;
    z-index: 30;
  }
  .el-cascader {
    .el-input__inner {
      padding-left: 30px;
    }
  }
  // .el-input__inner {
  //   width: 177px;
  //   height: 33px;
  //   background: #ffffff;
  //   border-radius: 4px;
  //   border: 1px solid #b4b2b3;
  // }
  .el-select,
  .el-cascader {
    .el-input__inner {
      width: 177px;
      height: 33px;
      background: #ffffff;
      border-radius: 4px;
      border: 1px solid #b4b2b3;
    }
    .el-input__suffix-inner {
      border-left: 1px solid #b4b2b3;
    }
  }
  .el-date-editor {
    width: 200px !important;
    .el-input__inner {
      width: 200px !important;
      height: 33px;
      background: #ffffff;
      border-radius: 4px;
      border: 1px solid #b4b2b3;
    }
    .el-icon-time::before {
      content: none;
    }
    .el-icon-time {
      // display: none !important;
      background-image: url("../img/home/alarmlist/time.png"); /* 替换为你自己的图标路径 */
      background-repeat: no-repeat;
      background-position: center;
      width: 16px; /* 图标大小 */
      height: 16px;
      display: inline-block;
      margin-top: 10px;
      margin-left: 4px;
    }
    .el-input__suffix-inner {
      display: inline-block;
      width: 15px;
      height: 15px;
      border-left: 1px solid #b4b2b3;
      margin-top: 11px;
      margin-right: 8px;

      .el-input__icon::before {
        content: "";
        position: absolute;
        top: 3px;
        left: 5px;
        width: 14px;
        height: 14px;
        border: 1px solid #b4b2b3;
        transform: rotate(45deg);
        clip-path: polygon(50% 50%, 100% 50%, 100% 100%, 50% 100%);
      }
    }
  }
}
.bjtj {
  width: 100%;
  height: 100%;
  background-color: #ffffff;
  border-radius: 6px;
  .serch {
    height: 100px;
    padding-top: 16px;
    padding-bottom: 16px;
    box-sizing: border-box;
    position: relative;
    .demo-ruleForm {
      height: 100%;
      display: flex;
      justify-content: left;
      align-items: flex-start;
      flex-wrap: wrap;
    }
  }
  .echarts {
    width: 100%;
    height: calc(100% - 100px);
    ::v-deep .el-empty {
      width: 307px;
      height: 353px;
      position: absolute;
      top: 50%;
      left: 50%;
      margin-left: -200px;
      margin-top: -200px;
      .el-empty__image img {
        vertical-align: top;
        height: 147%;
        width: 100%;
      }
      .el-empty__description {
        margin-top: 20px;
        margin-right: 70px;
      }
    }
  }
}
</style>
